INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — FTF + FTP interaction calculation
(3, 'Federal Tax Procedures', 'Dawson owes $20,000 in federal income tax for 2024 and files the return 7 months late without an extension. Dawson pays the full balance on the filing date. Evaluate the total combined failure-to-file and failure-to-pay penalties under Section 6651, considering the statutory maximums and the interaction rule between the two penalties.', '["$5,200", "$5,700", "$6,000", "$7,700"]'::jsonb, 0, 'Correct (A): Section 6651 imposes FTF at 5% per month (max 25%) and FTP at 0.5% per month (max 25%). FTF maxes at 25% after 5 months. When both penalties run concurrently, FTF is reduced by the FTP amount. Net FTF = 25% - (0.5% x 5 overlap months) = 22.5%. FTP = 0.5% x 7 months = 3.5%. Total = 26% x $20,000 = $5,200. Wrong (B): $5,700 incorrectly applies the FTF maximum without the FTP reduction for overlap months. Wrong (C): $6,000 incorrectly calculates 30% without applying the interaction rule. Wrong (D): $7,700 incorrectly adds FTF and FTP without applying the 25% FTF cap.', 'hard', 4),

-- Q2: easy / L1 — Correspondence audit definition
(3, 'Federal Tax Procedures', 'What type of IRS examination is conducted entirely through the mail?', '["Office audit", "Correspondence audit", "Field audit", "Criminal investigation"]'::jsonb, 1, 'Correct (B): A correspondence audit is the simplest IRS examination, conducted entirely by mail. The IRS sends a letter requesting documentation for a specific return item, and the taxpayer responds with records. No in-person meeting occurs. Wrong (A): An office audit requires the taxpayer to meet with an IRS examiner at the IRS office. Wrong (C): A field audit is conducted at the taxpayer''s location. Wrong (D): A criminal investigation is not an audit type but a separate enforcement action.', 'easy', 1),

-- Q3: hard / L4 — Evaluating court forum selection with multiple competing factors
(3, 'Federal Tax Procedures', 'Hensley receives a statutory notice of deficiency for $120,000. Hensley cannot afford to prepay the disputed amount, wants specialized tax expertise on the bench, and prefers to litigate locally rather than travel to Washington, D.C. However, Hensley also strongly desires a jury trial. Evaluate which forum best serves Hensley''s needs given these competing priorities and identify which preference must be sacrificed.', '["District Court — sacrifice the prepayment constraint", "Court of Federal Claims — sacrifice the local venue preference", "Tax Court — sacrifice the jury trial preference", "Tax Court Small Case Division — sacrifice the appeal rights"]'::jsonb, 2, 'Correct (C): The Tax Court is the only forum not requiring prepayment, offers specialized tax judges, and judges travel to the taxpayer''s city. It satisfies three of four preferences. However, the Tax Court does not offer jury trials — only U.S. District Court does. Hensley must sacrifice the jury trial preference. Wrong (A): District Court requires full prepayment, which Hensley cannot afford. Wrong (B): Court of Federal Claims requires prepayment and sits only in Washington, D.C., failing two preferences. Wrong (D): The Small Case Division has a $50,000 limit and the disputed amount is $120,000.', 'hard', 4),

-- Q4: easy / L1 — Tax lien definition
(3, 'Federal Tax Procedures', 'What is a federal tax lien?', '["A seizure of property to satisfy a tax debt", "An IRS payment plan for delinquent taxpayers", "A criminal charge for tax evasion", "A legal claim against a taxpayer''s property arising upon assessment and demand for payment"]'::jsonb, 3, 'Correct (D): Under IRC Section 6321, a federal tax lien is a legal claim (encumbrance) against all of a taxpayer''s property and rights to property that arises automatically when tax is assessed and the taxpayer fails to pay after demand. Wrong (A): A seizure of property describes a tax levy, not a lien. Wrong (B): A payment plan is an installment agreement, which is a separate IRS collection alternative. Wrong (C): A criminal charge relates to tax fraud prosecution, not the civil collection process.', 'easy', 1),

-- Q5: medium / L3 — Applying refund claim deadline rules
(3, 'Federal Tax Procedures', 'Nakamura filed a 2021 return on April 15, 2022, and paid all tax due on that date. In February 2025, Nakamura discovers an overlooked deduction worth $3,200 in refund. Nakamura files an amended return on March 10, 2025. Apply the refund claim deadline rules to determine the outcome.', '["The claim is timely under the 3-year rule because it is filed within 3 years of the April 15, 2022 filing date", "The claim is timely under the 2-year rule but the refund is limited to tax paid within 2 years of the claim", "The claim is untimely because the 3-year window from the due date expired April 15, 2025", "The claim is timely because the statute of limitations does not apply to amended returns"]'::jsonb, 0, 'Correct (A): Under Section 6511, a refund claim must be filed within the later of 3 years from the date the return was filed or 2 years from the date tax was paid. Nakamura filed on April 15, 2022. The 3-year deadline is April 15, 2025. The March 10, 2025 claim falls within this window, making it timely. The refund is limited to tax paid within the 3-year lookback period. Wrong (B): While the 2-year rule is an alternative, the 3-year rule is the applicable and more favorable deadline here. Wrong (C): The claim was filed before April 15, 2025, so the 3-year window has not expired. Wrong (D): Amended returns are subject to the same refund claim deadlines under Section 6511.', 'medium', 3),

-- Q6: medium / L2 — Classifying the 30-day letter
(3, 'Federal Tax Procedures', 'After completing an audit of Rivera''s 2023 return, the IRS sends a letter proposing adjustments that would increase Rivera''s tax liability by $18,000. The letter states that Rivera has 30 days to agree, submit additional documentation, or request an Appeals conference. Identify what this communication is called in the IRS assessment process.', '["Statutory notice of deficiency", "30-day letter (preliminary notice of proposed changes)", "Notice of Federal Tax Lien", "Notice of Intent to Levy"]'::jsonb, 1, 'Correct (B): The 30-day letter is a preliminary notice sent after an audit concludes, proposing changes and giving the taxpayer 30 days to agree, provide documentation, or request Appeals. It is the first formal step in the assessment process. Wrong (A): The statutory notice of deficiency (90-day letter) comes later if the taxpayer disagrees, and is required before the IRS can assess tax. Wrong (C): A Notice of Federal Tax Lien is filed after assessment to provide public notice of the lien. Wrong (D): A Notice of Intent to Levy is a collection action sent at least 30 days before property seizure.', 'medium', 2),

-- Q7: medium / L3 — Applying levy notice requirements
(3, 'Federal Tax Procedures', 'The IRS assessed a $45,000 tax deficiency against Thornton on June 1, 2025, and sent a demand for payment. Thornton did not pay. On July 15, 2025, the IRS levied Thornton''s bank account without sending any prior levy notice. Apply the collection procedural requirements to determine whether the IRS acted properly.', '["The IRS acted properly because a levy is automatic after assessment and demand", "The IRS acted properly because bank accounts are exempt from the notice requirement", "The levy was improper because the IRS must provide a Notice of Intent to Levy at least 30 days before seizing property", "The levy was improper because the IRS must wait 10 years before levying any property"]'::jsonb, 2, 'Correct (C): Under IRC Section 6331, before levying a taxpayer''s property, the IRS must provide a Notice of Intent to Levy at least 30 days in advance. The IRS levied Thornton''s bank account only 44 days after assessment without sending this required notice, making the levy procedurally improper. Wrong (A): While a lien arises automatically upon assessment and demand, a levy requires the additional 30-day notice. Wrong (B): Bank accounts are not exempt from the levy notice requirement. Wrong (D): The 10-year period is the collection statute of limitations, not a waiting period before levy.', 'medium', 3),

-- Q8: medium / L3 — Applying hazards of litigation standard
(3, 'Federal Tax Procedures', 'Garcia disputes a $60,000 deficiency and requests an Appeals conference. The Appeals officer reviews the case and determines that the IRS has only a 40% chance of prevailing in court on the primary issue. Apply the Appeals settlement framework to determine the most likely outcome.', '["Appeals will sustain the full $60,000 deficiency because it cannot reduce assessed amounts", "Appeals will dismiss the case because the IRS has less than a 50% chance of winning", "Appeals will refer the case to the Tax Court for resolution", "Appeals will likely offer a settlement reflecting the hazards of litigation, potentially conceding a portion of the $60,000"]'::jsonb, 3, 'Correct (D): The IRS Independent Office of Appeals settles cases based on the hazards of litigation — the probability of the IRS prevailing in court. With only a 40% chance of winning, Appeals would likely offer a settlement conceding a significant portion of the disputed amount to reflect the litigation risk. Wrong (A): Appeals has authority to settle and compromise tax disputes; it is not required to sustain the full deficiency. Wrong (B): Appeals does not dismiss cases — it settles or sustains based on the merits. Wrong (C): Appeals resolves cases administratively; referral to Tax Court is not part of the Appeals process.', 'medium', 3),

-- Q9: medium / L3 — Applying estimated tax safe harbor for high-income taxpayer
(3, 'Federal Tax Procedures', 'Whitfield had adjusted gross income of $200,000 on the 2024 return and expects to owe $30,000 in tax for 2025 after withholding. Whitfield wants to avoid the estimated tax penalty entirely. Apply the safe harbor rules to determine the minimum estimated tax payments Whitfield must make for 2025.', '["110% of the 2024 tax liability or 90% of the 2025 tax liability, whichever is less", "100% of the 2024 tax liability regardless of income level", "90% of the 2025 tax liability only — prior-year safe harbor does not apply above $150,000 AGI", "Either 100% of the 2024 tax liability or 90% of the 2025 tax liability, whichever is less"]'::jsonb, 0, 'Correct (A): Under IRC Section 6654, individuals with prior-year AGI exceeding $150,000 must pay the lesser of 90% of current-year tax or 110% of prior-year tax to avoid the estimated tax penalty. Since Whitfield''s 2024 AGI was $200,000 (exceeding $150,000), the 110% threshold applies instead of the standard 100%. Wrong (B): The 100% safe harbor applies only when prior-year AGI is $150,000 or less. Wrong (C): The prior-year safe harbor still applies above $150,000 AGI — it is simply increased to 110%. Wrong (D): This uses the standard 100% threshold, which is incorrect for taxpayers with AGI above $150,000.', 'medium', 3),

-- Q10: easy / L1 — 10-year collection statute
(3, 'Federal Tax Procedures', 'How long does the IRS generally have to collect a tax debt after assessment?', '["3 years", "10 years", "6 years", "20 years"]'::jsonb, 1, 'Correct (B): Under IRC Section 6502, the IRS generally has 10 years from the date of assessment to collect a tax debt. After this collection statute expires, the IRS can no longer pursue collection actions. Wrong (A): Three years is the general statute of limitations for assessment, not collection. Wrong (C): Six years is the extended assessment period for omissions exceeding 25% of gross income. Wrong (D): There is no 20-year collection period in the Internal Revenue Code.', 'easy', 1),

-- Q11: medium / L2 — Written protest vs small case request threshold
(3, 'Federal Tax Procedures', 'Palmer receives a 30-day letter proposing a $32,000 increase in tax liability and wants to request an Appeals conference. Identify the correct procedural requirement for Palmer to pursue administrative Appeals.', '["Palmer may submit a small case request because the amount is under $50,000", "Palmer may call the IRS to request an informal conference with no written submission", "Palmer must file a written protest because the disputed amount exceeds $25,000", "Palmer must file a petition with the Tax Court before requesting Appeals"]'::jsonb, 2, 'Correct (C): When the disputed amount exceeds $25,000, the taxpayer must file a formal written protest to request an Appeals conference. The small case request procedure is only available for disputes of $25,000 or less. Since Palmer''s dispute is $32,000, a written protest is required. Wrong (A): The small case request threshold is $25,000, not $50,000 — and $32,000 exceeds this limit. Wrong (B): Requesting Appeals requires a written submission; an informal phone call is insufficient. Wrong (D): A Tax Court petition is a judicial remedy, not a prerequisite for administrative Appeals.', 'medium', 2),

-- Q12: easy / L1 — Interest on underpayments cannot be abated
(3, 'Federal Tax Procedures', 'Which statement about interest on tax underpayments is correct?', '["Interest can be waived if the taxpayer demonstrates reasonable cause", "Interest is calculated using a flat 5% annual rate set by Congress", "Interest accrues only from the extended due date if an extension was filed", "Interest generally cannot be abated for reasonable cause"]'::jsonb, 3, 'Correct (D): Unlike penalties, interest on tax underpayments generally cannot be abated for reasonable cause. The IRS has limited authority to abate interest only when it results from unreasonable IRS delays in performing ministerial or managerial acts. Wrong (A): Reasonable cause is a defense to penalties under Section 6664, but it does not apply to interest abatement. Wrong (B): Interest is calculated using the federal short-term rate plus 3 percentage points, adjusted quarterly — not a flat 5%. Wrong (C): Interest accrues from the original due date of the return, without regard to extensions.', 'easy', 1),

-- Q13: medium / L3 — Applying the gross valuation misstatement penalty escalation
(3, 'Federal Tax Procedures', 'Fletcher claims a charitable contribution deduction of $500,000 for donated artwork. An independent appraisal determines the artwork''s fair market value is $200,000. Apply the valuation misstatement rules under Section 6662 to determine the applicable penalty.', '["A 40% penalty applies because the claimed value ($500,000) is 250% of the correct value ($200,000), constituting a gross valuation misstatement", "A 20% penalty applies because the claimed value exceeds 150% of the correct value, constituting a substantial valuation misstatement only", "No penalty applies because charitable contribution valuations are exempt from Section 6662", "A 75% penalty applies because overvaluation of property is treated as civil fraud"]'::jsonb, 0, 'Correct (A): Under Section 6662(h), a gross valuation misstatement occurs when the claimed value is 200% or more of the correct amount. Fletcher claimed $500,000 for artwork worth $200,000 — a ratio of 250%. This exceeds the 200% threshold, triggering the enhanced 40% penalty rather than the standard 20%. Wrong (B): While the 150% threshold for a substantial valuation misstatement is also met, the 200% gross misstatement threshold supersedes it with the higher 40% penalty. Wrong (C): Charitable contributions are not exempt from valuation misstatement penalties. Wrong (D): The 75% penalty applies only to civil fraud under Section 6663, which requires intent to evade tax.', 'medium', 3),

-- Q14: easy / L2 — Classifying the tax levy
(3, 'Federal Tax Procedures', 'The IRS sends Prescott a notice and then seizes funds from Prescott''s bank account to satisfy a $15,000 tax debt. Identify the IRS collection action used in this scenario.', '["Tax lien", "Tax levy", "Garnishment order", "Revenue ruling"]'::jsonb, 1, 'Correct (B): A tax levy is the actual seizure of a taxpayer''s property — including bank accounts, wages, and other assets — to satisfy a tax debt. The IRS seizing Prescott''s bank funds is a levy. Wrong (A): A tax lien is a legal claim against property, not a seizure — the lien attaches to property but does not take it. Wrong (C): While similar to garnishment, the IRS collection action is specifically called a levy under IRC Section 6331. Wrong (D): A revenue ruling is an IRS interpretation of tax law, unrelated to collection actions.', 'easy', 2),

-- Q15: easy / L1 — Civil fraud penalty rate
(3, 'Federal Tax Procedures', 'What is the penalty rate for civil fraud under Section 6663?', '["20% of the underpayment", "50% of the underpayment", "75% of the underpayment", "100% of the underpayment"]'::jsonb, 2, 'Correct (C): Section 6663 imposes a civil fraud penalty of 75% of the portion of the underpayment attributable to fraud. The IRS must prove fraud by clear and convincing evidence. Wrong (A): The 20% rate is the accuracy-related penalty under Section 6662, not the fraud penalty. Wrong (B): There is no 50% fraud penalty rate in the Internal Revenue Code. Wrong (D): The civil fraud penalty is 75%, not 100% of the underpayment.', 'easy', 1),

-- Q16: hard / L3 — Applying FTF/FTP combined penalty with fraudulent failure to file
(3, 'Federal Tax Procedures', 'The IRS determines that Morgan fraudulently failed to file a 2023 return. Morgan owed $40,000 in tax and eventually filed 6 months late. Apply the fraudulent failure-to-file penalty provisions under Section 6651(f) to calculate the failure-to-file penalty amount, considering the statutory maximum.', '["$10,000 (25% of unpaid tax)", "$24,000 (60% of unpaid tax)", "$36,000 (90% of unpaid tax)", "$30,000 (75% of unpaid tax)"]'::jsonb, 3, 'Correct (D): Under Section 6651(f), a fraudulent failure to file carries a penalty of 15% of unpaid tax per month, up to a maximum of 75%. For 6 months: 15% x 5 months = 75% (max reached at month 5). The penalty is 75% x $40,000 = $30,000. The 75% maximum is reached after 5 months. Wrong (A): The 25% maximum applies to the standard (non-fraudulent) failure-to-file penalty. Wrong (B): 60% would imply 4 months at 15%, but the penalty continues to month 5 where it reaches the 75% cap. Wrong (C): 90% would exceed the 75% statutory maximum for fraudulent failure to file.', 'hard', 3),

-- Q17: medium / L2 — Identifying appeals route from Court of Federal Claims
(3, 'Federal Tax Procedures', 'Carpenter loses a tax case in the U.S. Court of Federal Claims and wants to appeal. Identify the correct appellate court for this appeal.', '["U.S. Court of Appeals for the Federal Circuit", "U.S. Court of Appeals for the taxpayer''s geographic circuit", "U.S. Supreme Court (direct appeal)", "U.S. Tax Court appellate division"]'::jsonb, 0, 'Correct (A): Decisions of the U.S. Court of Federal Claims are appealed to the U.S. Court of Appeals for the Federal Circuit. This differs from Tax Court and District Court decisions, which are appealed to the taxpayer''s geographic circuit court. Wrong (B): Geographic circuit appeals apply to Tax Court and District Court decisions, not Court of Federal Claims. Wrong (C): Cases cannot be directly appealed to the U.S. Supreme Court from the Court of Federal Claims. Wrong (D): There is no Tax Court appellate division — the Tax Court is a trial-level court.', 'medium', 2),

-- Q18: easy / L1 — Failure to pay penalty rate
(3, 'Federal Tax Procedures', 'What is the monthly rate for the failure-to-pay penalty under Section 6651?', '["5% per month", "0.5% per month", "1% per month", "2.5% per month"]'::jsonb, 1, 'Correct (B): Under Section 6651(a)(2), the failure-to-pay penalty accrues at 0.5% of the unpaid tax per month (or fraction of a month), up to a maximum of 25%. This rate is one-tenth of the failure-to-file rate. Wrong (A): 5% per month is the failure-to-file penalty rate, not the failure-to-pay rate. Wrong (C): There is no 1% monthly penalty rate under Section 6651. Wrong (D): 2.5% is not a penalty rate established under the failure-to-pay provisions.', 'easy', 1),

-- Q19: medium / L2 — Identifying the Tax Court small case threshold
(3, 'Federal Tax Procedures', 'Burton has a $35,000 tax dispute and is considering the Tax Court''s Small Case Division for a simplified proceeding. Identify the key limitation that applies if Burton elects this division.', '["The case must involve only individual taxpayers, not businesses", "The small case division only hears cases involving penalties, not deficiencies", "The taxpayer waives the right to appeal the decision", "The taxpayer must prepay 50% of the disputed amount"]'::jsonb, 2, 'Correct (C): The Tax Court Small Case Division (Section 7463) handles disputes of $50,000 or less using simplified procedures. However, the critical limitation is that the decision is final and cannot be appealed by either party. Burton''s $35,000 dispute qualifies, but the appeal waiver is significant. Wrong (A): The Small Case Division is not limited to individual taxpayers. Wrong (B): The division hears deficiency cases, not just penalty disputes. Wrong (D): No prepayment is required in Tax Court, including the Small Case Division.', 'medium', 2),

-- Q20: medium / L2 — Identifying the interest rate on underpayments
(3, 'Federal Tax Procedures', 'Kessler owes $25,000 in additional tax after an audit. The IRS calculates interest on the underpayment. Identify the correct interest rate formula used for individual taxpayers under the Internal Revenue Code.', '["Prime rate plus 2 percentage points, adjusted annually", "A flat 6% annual rate set by statute", "10% of the underpayment, compounded monthly", "Federal short-term rate plus 3 percentage points, adjusted quarterly"]'::jsonb, 3, 'Correct (D): Under IRC Section 6621, interest on tax underpayments for individuals is calculated at the federal short-term rate plus 3 percentage points, adjusted quarterly. Interest is compounded daily. Wrong (A): The IRS does not use the prime rate for underpayment interest calculations. Wrong (B): The interest rate is not a flat statutory rate — it fluctuates with the federal short-term rate. Wrong (C): Interest is not calculated as a percentage of the underpayment; it is an annual rate compounded daily.', 'medium', 2),

-- Q21: hard / L4 — Evaluating which penalty applies when both fraud and accuracy-related are alleged
(3, 'Federal Tax Procedures', 'The IRS audits Maxwell and proposes a $80,000 underpayment. The IRS alleges that $50,000 of the underpayment is due to civil fraud (supported by fabricated invoices) and $30,000 is due to negligence (careless recordkeeping). Maxwell''s attorney argues reasonable cause for the negligence portion. Evaluate the penalty exposure for the entire $80,000 underpayment, considering Section 6662 and Section 6663 interaction rules.', '["$37,500 fraud penalty on the fraud portion only; no accuracy-related penalty on the negligence portion if reasonable cause is established", "$60,000 fraud penalty on the entire underpayment because any fraud taints the whole amount", "$37,500 fraud penalty on the fraud portion plus $6,000 accuracy-related penalty on the negligence portion", "$43,500 fraud penalty on the fraud portion plus accuracy-related penalty on the remainder"]'::jsonb, 0, 'Correct (A): Under Section 6663, the fraud penalty (75%) applies to the portion attributable to fraud: 75% x $50,000 = $37,500. Sections 6662 and 6663 cannot both apply to the same portion of an underpayment. For the $30,000 negligence portion, the accuracy-related penalty (20%) would normally apply, but Section 6664(c) provides a defense if the taxpayer had reasonable cause and acted in good faith. If Maxwell establishes reasonable cause for the negligence portion, no penalty applies to that $30,000. Wrong (B): The entire underpayment is presumed fraudulent only if the IRS proves any portion is fraudulent and the taxpayer fails to prove otherwise for specific portions — but Maxwell''s attorney can establish the negligence portion was not fraudulent. Wrong (C): This assumes both penalties apply simultaneously, but reasonable cause could eliminate the accuracy penalty. Wrong (D): This incorrectly combines the penalty amounts.', 'hard', 4),

-- Q22: easy / L1 — 90-day letter for overseas taxpayers
(3, 'Federal Tax Procedures', 'How many days does a taxpayer residing outside the United States have to petition the Tax Court after receiving a statutory notice of deficiency?', '["90 days", "150 days", "30 days", "180 days"]'::jsonb, 1, 'Correct (B): Under IRC Section 6213, a taxpayer who is outside the United States when the statutory notice of deficiency is mailed has 150 days (rather than the standard 90 days) to file a petition with the Tax Court. Wrong (A): 90 days is the standard period for taxpayers within the United States. Wrong (C): 30 days is the response period for a preliminary 30-day letter, not the statutory notice of deficiency. Wrong (D): There is no 180-day petition period in the statute.', 'easy', 1),

-- Q23: medium / L2 — Notice of Federal Tax Lien purpose
(3, 'Federal Tax Procedures', 'After assessing a $90,000 tax liability against Sutton, the IRS files a Notice of Federal Tax Lien (NFTL) with the county recorder''s office. Identify the primary purpose of filing this notice.', '["To seize Sutton''s property and sell it at auction", "To freeze Sutton''s bank accounts pending payment", "To provide public notice and establish the IRS''s priority against other creditors", "To initiate criminal proceedings against Sutton for tax evasion"]'::jsonb, 2, 'Correct (C): The Notice of Federal Tax Lien (NFTL) is filed to provide public notice of the government''s legal claim against the taxpayer''s property and to establish priority against other creditors. The lien itself arises automatically upon assessment and demand, but the NFTL makes it a matter of public record. Wrong (A): Seizing and selling property is a levy action, not a lien filing. Wrong (B): Freezing bank accounts is a form of levy, not a lien. Wrong (D): Filing an NFTL is a civil collection action, not a criminal proceeding.', 'medium', 2),

-- Q24: medium / L2 — Large corporate underpayment interest rate
(3, 'Federal Tax Procedures', 'Meridian Corp. has a tax underpayment of $250,000 following an audit. The IRS calculates interest on the underpayment. Identify the interest rate that applies to the portion of Meridian''s underpayment that exceeds $100,000.', '["Federal short-term rate plus 3 percentage points", "Federal short-term rate plus 1 percentage point", "The standard individual underpayment rate with no corporate adjustment", "Federal short-term rate plus 5 percentage points"]'::jsonb, 3, 'Correct (D): Under IRC Section 6621(c), large corporate underpayments — the portion exceeding $100,000 — are subject to an increased interest rate equal to the federal short-term rate plus 5 percentage points, rather than the standard rate of the short-term rate plus 3 points. Wrong (A): The short-term rate plus 3 points is the standard rate for individual underpayments and the first $100,000 of corporate underpayments. Wrong (B): The short-term rate plus 1 point applies to corporate overpayments, not underpayments. Wrong (C): A special corporate adjustment applies to large underpayments exceeding $100,000.', 'medium', 2),

-- Q25: medium / L3 — Applying the 25% omission test to business gross income
(3, 'Federal Tax Procedures', 'Ortega operates a sole proprietorship with $400,000 in gross receipts and $280,000 in cost of goods sold for 2022. Ortega''s return reported only $280,000 in gross receipts, omitting $120,000. The return was filed timely on April 15, 2023. Apply the 25% gross income omission rule under Section 6501(e) to determine whether the IRS has 3 or 6 years to assess additional tax.', '["The 6-year statute applies because the $120,000 omission exceeds 25% of gross receipts ($400,000)", "The 3-year statute applies because the omission does not exceed 25% of net income after COGS", "The 3-year statute applies because the 25% test uses taxable income, not gross receipts", "The 6-year statute applies only if the omission was intentional"]'::jsonb, 0, 'Correct (A): Under Section 6501(e), the 6-year statute applies when the taxpayer omits more than 25% of gross income. For a trade or business, gross income means gross receipts before deducting cost of goods sold. Ortega omitted $120,000 of $400,000 gross receipts = 30%, which exceeds the 25% threshold. The 6-year statute applies through April 15, 2029. Wrong (B): The 25% test uses gross receipts, not net income after COGS. Using net income ($120,000) would give 100%, which also exceeds 25%, but the statutory measure is gross receipts. Wrong (C): The test uses gross income (gross receipts for businesses), not taxable income. Wrong (D): The 6-year statute applies regardless of intent — intent is relevant to the unlimited fraud statute, not the 25% omission rule.', 'medium', 3),

-- Q26: medium / L3 — Applying lien vs levy distinction in collection scenario
(3, 'Federal Tax Procedures', 'The IRS assesses a $70,000 deficiency against Patel and sends a demand for payment. Patel does not pay. The IRS wants to protect its claim against Patel''s property before other creditors can attach it, but does not yet want to seize any assets. Apply the distinction between collection tools to identify the appropriate IRS action.', '["Issue a tax levy against Patel''s bank account", "File a Notice of Federal Tax Lien to establish priority against other creditors without seizing assets", "Initiate a criminal investigation for failure to pay", "Offset Patel''s future refunds only — no other action is available until the 10-year collection period expires"]'::jsonb, 1, 'Correct (B): A federal tax lien is a legal claim that attaches to the taxpayer''s property upon assessment and demand. Filing a Notice of Federal Tax Lien (NFTL) provides public notice and establishes the IRS''s priority against other creditors. Importantly, a lien is an encumbrance, not a seizure — it protects the IRS''s interest without taking the taxpayer''s property. Wrong (A): A levy would seize assets, which the IRS specifically wants to avoid at this stage. Wrong (C): Failure to pay a civil tax debt is not a criminal matter. Wrong (D): Refund offsets are one tool, but filing a lien is the appropriate action to protect priority against other creditors.', 'medium', 3),

-- Q27: easy / L1 — Estimated tax penalty threshold for individuals
(3, 'Federal Tax Procedures', 'At what minimum expected tax liability must an individual begin making estimated tax payments?', '["$500 or more", "$2,500 or more", "$1,000 or more", "$5,000 or more"]'::jsonb, 2, 'Correct (C): Under IRC Section 6654, individuals must make estimated tax payments if they expect to owe $1,000 or more in tax after subtracting withholding and credits. Failure to do so may result in an estimated tax penalty. Wrong (A): The $500 threshold applies to corporations under Section 6655, not individuals. Wrong (B): There is no $2,500 threshold for estimated tax payments. Wrong (D): $5,000 is not the statutory threshold for estimated tax payment requirements.', 'easy', 1),

-- Q28: hard / L4 — Evaluating refund claim with 2-year vs 3-year lookback
(3, 'Federal Tax Procedures', 'Ingram filed a 2020 return on April 15, 2021, showing $12,000 tax due. Ingram paid $8,000 through withholding during 2020 and $4,000 on April 15, 2021. After an IRS notice, Ingram made an additional $5,000 payment on August 1, 2023. On June 15, 2025, Ingram files a refund claim for $7,000. The 3-year deadline from filing expired April 15, 2024. Evaluate the claim under Section 6511''s lookback rules.', '["$7,000 — the full refund because Ingram made payments totaling $17,000", "No refund — the claim is untimely because the 3-year filing deadline has passed", "$12,000 — all original payments are recoverable under the 2-year rule", "$5,000 — the claim is timely under the 2-year rule from the August 2023 payment, but the refund is limited to tax paid within 2 years of the claim"]'::jsonb, 3, 'Correct (D): Under Section 6511, a refund claim must be filed within the later of 3 years from filing or 2 years from payment. The 3-year deadline expired April 15, 2024. However, the 2-year rule from the August 1, 2023 payment gives until August 1, 2025. The June 2025 claim is timely under this rule. When filing under the 2-year rule, the refund is limited to tax paid within 2 years of the claim (June 15, 2023 to June 15, 2025). Only the $5,000 paid August 1, 2023 falls within this window. Wrong (A): The full $7,000 is not available because the lookback limits the refund to $5,000. Wrong (B): The claim is timely under the alternative 2-year-from-payment rule. Wrong (C): The 2-year lookback only captures payments within 2 years of the claim, excluding the original 2021 payments.', 'hard', 4),

-- Q29: medium / L2 — Reasonable cause defense applicability
(3, 'Federal Tax Procedures', 'The IRS proposes a 20% accuracy-related penalty against Dunn for a $15,000 substantial understatement. Dunn''s CPA prepared the return and relied on a well-reasoned legal opinion from a tax attorney regarding the disputed position. Identify the defense most likely to eliminate the penalty.', '["Reasonable cause and good faith under Section 6664(c), supported by reliance on professional tax advice", "Statute of limitations expiration under Section 6501", "The de minimis exception for understatements below $25,000", "Voluntary disclosure to the IRS before the audit began"]'::jsonb, 0, 'Correct (A): Section 6664(c) provides that the accuracy-related penalty does not apply if the taxpayer had reasonable cause and acted in good faith. Reliance on a competent tax professional''s well-reasoned advice is a recognized reasonable cause defense, provided the taxpayer supplied accurate information to the advisor. Wrong (B): The statute of limitations relates to the IRS''s time to assess tax, not to penalty defenses. Wrong (C): There is no de minimis exception at $25,000 for accuracy-related penalties — the substantial understatement threshold is the greater of 10% of correct tax or $5,000. Wrong (D): Voluntary disclosure may reduce criminal exposure but is not a statutory defense to the accuracy-related penalty.', 'medium', 2),

-- Q30: hard / L4 — Evaluating interest netting for simultaneous over/underpayment
(3, 'Federal Tax Procedures', 'Sterling has a 2022 tax overpayment of $15,000 (resulting from excess withholding) and simultaneously owes an additional $10,000 in tax for 2022 due to unreported income discovered during an audit. Both amounts accrue interest from the April 2023 due date. Evaluate how the IRS handles the interest calculation when a taxpayer has both an overpayment and an underpayment for the same tax period.', '["Interest on the overpayment and underpayment are calculated independently with no offset", "The IRS nets the overpayment against the underpayment to reduce the interest differential, eliminating interest on the overlapping $10,000 amount", "The IRS charges underpayment interest on $10,000 but pays no overpayment interest because audited taxpayers forfeit refund interest", "The IRS applies overpayment interest to the full $15,000 and underpayment interest to the full $10,000, then subtracts the smaller from the larger"]'::jsonb, 1, 'Correct (B): Under IRC Section 6621(d), when a taxpayer has both an overpayment and an underpayment for the same tax period, the IRS nets them to reduce the interest differential. The overlapping $10,000 is offset, eliminating interest charges on that amount. Interest accrues only on the net $5,000 overpayment. This prevents the IRS from charging a higher underpayment rate while paying a lower overpayment rate on the same money. Wrong (A): Independent calculation without netting would unfairly penalize the taxpayer due to the rate differential. Wrong (C): Audited taxpayers do not forfeit overpayment interest. Wrong (D): This describes gross calculation without proper netting — the statute requires offsetting the overlapping amounts.', 'hard', 4)
;

COMMIT;
